; ---- entry: replaces `movea.l $1008.w,a5 / moveq #0,d0` at the start of the face routine $f90c (called after the ticker in every HUD stage, also in the extra frames).
; Registers: the stock face path clobbers d0-d7 a0-a4 a6 (its sprite kernel), its callers rely on nothing but a5 = $1008: this code uses exactly those and keeps a5.
sbent:  movea.l $1008.w,a5              ; the buffer being drawn
        cmpi.l  #$0000ffff,2560(a5)     ; sentinel: planes 0/1 of the first strip word = $0000 $ffff in the black strip; $ffff $ffff in the sky the HUD paints over rows 16-64; 0 in a cleared screen
        bne.w   repaint
back:   move.l  a5,d0
        lea     S0.l,a0                 ; this buffer's shadow: +0 message drawn (word, 0 = none), +2 characters drawn, +4 face frame drawn (0 = none), +6 dirty text lines (bit 0/1)
        btst    #15,d0
        beq.s   .s0
        lea     S1.l,a0
.s0:    tst.b   $11ab.w                 ; the ticker: 0 = no message on screen (idle, or the erase passes), 1 = typing, >= 2 = held
        bne.s   active
none:   tst.w   (a0)
        bne.s   endmsg
        tst.w   4(a0)
        beq.s   out
endmsg:   bsr     clrtext                 ; the message ended: this buffer still shows it -> solid fill of the dirty text lines and the face box, once
        tst.w   4(a0)
        beq.s   .nf
        bsr     clrface
.nf:    clr.l   (a0)
        clr.w   4(a0)
out:    moveq   #0,d0                   ; the displaced `moveq #0,d0`; continue in the face routine
        jmp     $f912.l

active: move.w  $11a8.w,d1              ; message record address (low word); the text starts 4 bytes behind it (x, y, colour, hold)
        beq.s   none
        move.w  $11a4.w,d2              ; ticker text pointer (low word of $11a2): characters typed so far = pointer - text start
        sub.w   d1,d2
        subq.w  #4,d2
        cmp.w   (a0),d1
        bne.s   work
        cmp.w   2(a0),d2
        beq.s   out                     ; this buffer already shows exactly this: nothing to do
work:   cmp.w   #256,d2
        bcs.s   .nok
        moveq   #0,d2
.nok:   moveq   #0,d3
        move.w  d1,d3
        addq.l  #4,d3
        movea.l d3,a2                   ; a2 = the message text
        lea     LM.l,a3                 ; shared layout state: +0 message, +2 characters laid out, +4 column, +6 line offset (0 / 1600), +8 at-word-start flag
        cmp.w   (a3),d1
        bne.s   .newl
        cmp.w   2(a3),d2
        bcc.s   .lay
.newl:  move.w  d1,(a3)
        clr.w   2(a3)
        clr.w   4(a3)
        clr.w   6(a3)
        move.w  #1,8(a3)
.lay:   movem.w 2(a3),d4-d7            ; characters laid out, column, line offset, at-word-start (sign-extended words)
        cmp.w   d2,d4
        bcc.w   .draw
        lea     CELL.l,a4
        lea     COLO(pc),a1
.lc:    moveq   #0,d0
        move.b  (a2,d4.w),d0
        cmp.b   #$20,d0
        beq.s   .sep
        cmp.b   #$0d,d0
        beq.s   .sep
        tst.w   d7                      ; a word starts here: does it fit on this line?
        beq.s   .inw
        moveq   #0,d7
        tst.w   d5
        beq.s   .inw
        move.w  d4,d1
.wl:    addq.w  #1,d1
        move.b  (a2,d1.w),d3
        beq.s   .wle
        cmp.b   #$20,d3
        beq.s   .wle
        cmp.b   #$0d,d3
        bne.s   .wl
.wle:   sub.w   d4,d1                   ; word length
        add.w   d5,d1
        cmp.w   #W,d1
        bls.s   .inw
        add.w   #1600,d6           ; wrap
        moveq   #0,d5
.inw:   cmp.w   #W,d5
        bcs.s   .fit
        add.w   #1600,d6
        moveq   #0,d5
.fit:   move.w  d4,d3
        lsl.w   #2,d3
        cmp.w   #3200,d6
        bcc.s   .skip
        sub.b   #32,d0          ; not a glyph of the table: no cell
        cmp.b   #91,d0
        bcc.s   .skip
        lsl.w   #5,d0                   ; glyph strip offset
        swap    d0
        move.w  d5,d1
        add.w   d1,d1
        move.w  (a1,d1.w),d1
        add.w   d6,d1
        move.w  d1,d0                   ; long = glyph offset << 16 | cell (byte offset of the glyph in the buffer)
        move.l  d0,(a4,d3.w)
        bra.s   .nx
.skip:  clr.l   (a4,d3.w)
.nx:    addq.w  #1,d5
        bra.s   .adv
.sep:   move.w  d4,d3
        lsl.w   #2,d3
        clr.l   (a4,d3.w)
        tst.w   d5
        beq.s   .s1
        cmp.w   #W,d5
        bcc.s   .s1
        addq.w  #1,d5
.s1:    moveq   #1,d7
.adv:   addq.w  #1,d4
        cmp.w   d2,d4
        bcs.w   .lc
        movem.w d4-d7,2(a3)
.draw:  move.w  (a3),d1                 ; message (the layout state holds it)
        cmp.w   (a0),d1
        bne.s   .chg
        move.w  2(a0),d4
        cmp.w   d2,d4
        bls.s   .dl0
.chg:   movem.l d1-d2/a2-a3,-(a7)      ; this buffer shows another message (or more than the current one): wipe its lines first (clrtext clobbers the pattern registers)
        bsr     clrtext
        movem.l (a7)+,d1-d2/a2-a3
        move.w  d1,(a0)
        clr.w   2(a0)
        clr.w   4(a0)                   ; and its face (a new message brings its own)
.dl0:   move.w  2(a0),d4
        cmp.w   d2,d4
        bcc.s   .dend
        lea     CELL.l,a4
        lea     FONT.l,a6
.dl:    move.w  d4,d3
        lsl.w   #2,d3
        move.l  (a4,d3.w),d0
        beq.s   .dn
        lea     (a5,d0.w),a3
        swap    d0
        lea     (a6,d0.w),a1

        move.l  (a1)+,d0
        movep.l d0,0(a3)
        move.l  (a1)+,d0
        movep.l d0,160(a3)
        move.l  (a1)+,d0
        movep.l d0,320(a3)
        move.l  (a1)+,d0
        movep.l d0,480(a3)
        move.l  (a1)+,d0
        movep.l d0,640(a3)
        move.l  (a1)+,d0
        movep.l d0,800(a3)
        move.l  (a1)+,d0
        movep.l d0,960(a3)
        move.l  (a1)+,d0
        movep.l d0,1120(a3)
.dn:    addq.w  #1,d4
        cmp.w   d2,d4
        bcs.s   .dl
.dend:  move.w  d2,2(a0)
        moveq   #1,d0                   ; dirty lines: line 0 always; line 1 when the layout has reached it
        tst.w   LM+6.l
        beq.s   .m0
        moveq   #3,d0
.m0:    or.b    d0,6(a0)
        bra     out

; ---- pattern registers: the black strip colour (index 2: plane 1 only) = per 16 pixels the words 0000 ffff 0000 0000 = the longs $0000ffff, 0 alternating
patload: move.l #$0000ffff,d0
        moveq   #0,d1
        move.l  d0,d2
        move.l  d1,d3
        move.l  d0,d4
        move.l  d1,d5
        movea.l d0,a1
        movea.l d1,a2
        movea.l d0,a3
        movea.l d1,a4
        rts

; ---- solid fill of the dirty text lines of this buffer (a0 = shadow, a5 = buffer); clobbers d0-d7 a1-a4 a6
clrtext: move.b 6(a0),d6
        beq.s   .ret
        clr.b   6(a0)
        bsr.s   patload
        btst    #0,d6
        beq.s   .l1
        lea     3200(a5),a6
        bsr.s   fill8
.l1:    btst    #1,d6
        beq.s   .ret
        lea     4800(a5),a6
        bsr.s   fill8
.ret:   rts
fill8:  moveq   #7,d7                   ; 8 rows x 152 bytes (groups 0-18)
.r:     movem.l d0-d5/a1-a4,(a6)
        movem.l d0-d5/a1-a4,40(a6)
        movem.l d0-d5/a1-a4,80(a6)
        movem.l d0-d5/a1-a2,120(a6)
        lea     160(a6),a6
        dbra    d7,.r
        rts

; ---- the face box (16x24 at x 304, group 19) -> black
clrface: lea    2872(a5),a6
        move.l  #$0000ffff,d0
        moveq   #0,d1
        moveq   #23,d7
.f:     move.l  d0,(a6)
        move.l  d1,4(a6)
        lea     160(a6),a6
        dbra    d7,.f
        rts

; ---- the strip was overpainted (race start / restart, first pass into a buffer): rows 16-41 black, shadows of this buffer cleared.
; The OTHER buffer (the one on screen) is checked too: the race restart paints sky into it as well (measured: race_drive restart, the displayed buffer's strip was all sky for the whole first pass),
; and a displayed buffer is only redrawn one pass later.
repaint: bsr     patload
        lea     2560(a5),a6
        bsr     fillstrip
